 52	/** Main-process only. Values never cross IPC; persistence always requires OS encryption. */
 53	export class SecretsStore {
 54	  private data: Partial<Record<SecretName, string>> = {};
 55	  private queue: Promise<unknown> = Promise.resolve();
 56	  private loading?: Promise<void>;
 57	  private storage?: SecureStorage;
 58	  private readonly environment: Record<string, string | undefined>;
 59	  private readonly platform: NodeJS.Platform;
 60	  constructor(
 61	    private readonly dir: string,
 62	    options: SecretsStoreOptions = {},
 63	  ) {
 64	    this.storage = options.secureStorage;
 65	    this.environment = options.environment ?? process.env;
 66	    this.platform = options.platform ?? process.platform;
 67	  }
 68	  private async resolveStorage(): Promise<void> {
 69	    if (this.storage) return;
 70	    try {
 71	      const electron = await import("electron");
 72	      this.storage = electron.safeStorage;
 73	    } catch {
 74	      // requireSecure supplies the stable, sanitized error. No plaintext fallback.
 75	    }
 76	  }
 77	  private requireSecure(): SecureStorage {
 78	    let available = false;
 79	    try {
 80	      available =
 81	        !!this.storage?.isEncryptionAvailable() &&
 82	        !(this.platform === "linux" && this.storage.getSelectedStorageBackend?.() === "basic_text");
 83	    } catch {
 84	      // Native keyring failures must not expose OS error details or enable a fallback.
 85	    }
 86	    if (!available)
 87	      throw new ReqflowError(
 88	        "secure_storage_unavailable",
 89	        "OS-backed credential encryption is unavailable. Configure a secure OS keyring; plaintext fallback is disabled.",
 90	      );
 91	    return this.storage!;
 92	  }
 93	  private decrypt(encrypted: string): string {
 94	    const storage = this.requireSecure();
 95	    try {
 96	      return Credential.parse(storage.decryptString(Buffer.from(encrypted, "base64")));
 97	    } catch {
 98	      throw storageError("Credential could not be decrypted with the OS keyring.");
 99	    }
100	  }
101	  private async read(name: string): Promise<Partial<Record<SecretName, string>> | undefined> {
102	    try {
103	      const path = join(this.dir, name);
104	      const info = await lstat(path);
105	      if (!info.isFile() || info.isSymbolicLink() || info.size > 1024 * 1024)
106	        throw new Error("Unsafe credential store");
107	      return Ciphertexts.parse(JSON.parse(await readFile(path, "utf8")));
108	    } catch (error) {
109	      if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
110	      throw storageError("Encrypted credential store could not be read.");
111	    }
112	  }
113	  private async persist(next: Partial<Record<SecretName, string>>): Promise<void> {
114	    await mkdir(this.dir, { recursive: true, mode: 0o700 });
115	    const temp = join(this.dir, `.secrets-${randomUUID()}.tmp`);
116	    try {
117	      await writeFile(temp, JSON.stringify(next), { mode: 0o600 });
118	      await rename(temp, join(this.dir, "secrets.enc.json"));
119	      this.data = next;
120	    } catch {
121	      throw storageError("Encrypted credential store could not be written.");
122	    } finally {
123	      await rm(temp, { force: true });
124	    }
125	  }
126	  load(): Promise<void> {
127	    return (this.loading ??= (async () => {
128	      const current = await this.read("secrets.enc.json");
129	      if (current !== undefined) {
130	        this.data = current;
131	        if (Object.keys(current).length) await this.resolveStorage();
132	        return;
133	      }
134	      const legacy = await this.read("secrets.json");
135	      if (legacy === undefined) return;
136	      await this.resolveStorage();
137	      // Old main builds also stored base64 plaintext. Only successful OS decryption proves
138	      // an entry is legitimate. Never decode it as UTF-8, and never hide failure with env.
139	      for (const encrypted of Object.values(legacy)) this.decrypt(encrypted);
140	      await this.persist(legacy); // Leave the original legacy file untouched.
141	    })());
142	  }
143	  async getSecret(input: SecretName): Promise<string | null> {
144	    const name = SecretName.parse(input);
145	    await this.load();
146	    return this.get(name) ?? null;
147	  }
148	  async setSecret(input: SecretName, value: string | null): Promise<void> {
149	    const name = SecretName.parse(input);
150	    const validated = value === null ? null : Credential.parse(value);
151	    const operation = this.queue.then(async () => {
152	      await this.load();
153	      const next = { ...this.data };
154	      if (validated === null) delete next[name];
155	      else {
156	        await this.resolveStorage();
157	        try {
158	          next[name] = this.requireSecure().encryptString(validated).toString("base64");
159	        } catch (error) {
160	          if (error instanceof ReqflowError) throw error;
161	          throw storageError("Credential could not be encrypted with the OS keyring.");
162	        }
163	      }
164	      await this.persist(next);
165	    });
166	    this.queue = operation.catch(() => {});
167	    await operation;
168	  }
169	  async getStatus(): Promise<SecretStatus> {
170	    await this.load();
171	    // Stored-but-undecryptable credentials must not look usable to provider gates.
172	    for (const name of SECRET_NAMES) this.get(name);
173	    return this.status();
174	  }
175	  /** Compatibility for the isolated legacy Research tests; production uses async methods. */
176	  get(input: SecretName): string | undefined {
177	    const name = SecretName.parse(input);
178	    if (this.data[name]) return this.decrypt(this.data[name]);
179	    const value = this.environment[ENV_VAR_MAP[name]];
180	    try {
181	      return value ? Credential.parse(value) : undefined;
182	    } catch {
183	      throw storageError("Environment credential failed validation.");
184	    }
185	  }
186	  status(): SecretStatus {
187	    return Object.fromEntries(
188	      SECRET_NAMES.map((name) => [
189	        name,
190	        {
191	          configured: !!(this.data[name] || this.environment[ENV_VAR_MAP[name]]),
192	          source: this.data[name] ? "keychain" : this.environment[ENV_VAR_MAP[name]] ? "env" : null,
193	        },
194	      ]),
195	    ) as SecretStatus;
196	  }
197	  async set(name: SecretName, value: string | null): Promise<SecretStatus> {
198	    await this.setSecret(name, value);
199	    return this.status();
200	  }
