 44	async function readOptional(path: string): Promise<unknown | undefined> {
 45	  try {
 46	    const info = await lstat(path);
 47	    if (!info.isFile() || info.isSymbolicLink() || info.size > PERSISTED_JSON_MAX_BYTES)
 48	      throw new Error("Unsafe legacy artifact");
 49	    return JSON.parse(await readFile(path, "utf8"));
 50	  } catch (error) {
 51	    if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
 52	    throw new ReqflowError(
 53	      "storage_error",
 54	      "Legacy Research data could not be read. Originals were left intact.",
 55	    );
 56	  }
 57	}
 58	async function atomicWrite(path: string, value: unknown) {
