 68	/** One-way additive migration. Current stores win conflicts; every legacy original stays intact. */
 69	export async function migrateLegacyResearch(
 70	  dir: string,
 71	  db: DatabaseSync,
 72	  files: LocalFileStore,
 73	  datasets: ResearchDatasetRepository,
 74	): Promise<void> {
 75	  const marker = join(dir, "research-sqlite-migration-v1.json");
 76	  const migrated = await readOptional(marker);
 77	  if (migrated !== undefined) {
 78	    if (
 79	      !z.object({ version: z.literal(1), migratedAt: z.iso.datetime() }).safeParse(migrated).success
 80	    )
 81	      throw new ReqflowError(
 82	        "storage_error",
 83	        "Legacy Research migration marker failed validation.",
 84	      );
 85	    return;
 86	  }
 87	  const raw = await readOptional(join(dir, "app-state.json"));
 88	  if (raw === undefined) return;
 89	  try {
 90	    const state = State.parse(raw);
 91	    for (const workflow of state.workflows) WorkflowId.parse(workflow.id);
 92	    for (const run of state.runs) {
 93	      RunId.parse(run.id);
 94	      WorkflowId.parse(run.workflowId);
 95	    }
 96	    const fileRaw = await readOptional(join(dir, "files.json"));
 97	    const imports = fileRaw === undefined ? [] : z.array(FileInfo).parse(fileRaw);
 98	    const runs = new SqliteRunRepository(db);
 99	    const known = new Set((await runs.list()).map((run) => run.id));
100	    // Validate all preservable artifacts before modifying the destination.
101	    const artifacts = await Promise.all(
102	      state.runs.map(async (run) => {
103	        const outputs = await readOptional(join(dir, `${run.id}.outputs.json`));
104	        if (outputs !== undefined)
105	          z.record(z.string(), z.record(z.string(), PipelineData)).parse(outputs);
106	        const value = await readOptional(join(dir, `${run.id}.research.json`));
107	        const dataset = value === undefined ? undefined : ResearchDataset.parse(value);
108	        if (dataset) {
109	          if (dataset.runId !== run.id) throw new Error("mismatched run");
110	          assertJsonByteBudget(dataset, RESEARCH_DATASET_MAX_BYTES);
111	        }
112	        return {
113	          run,
114	          outputs: outputs as Record<string, Record<string, PipelineData>> | undefined,
115	          dataset,
116	        };
117	      }),
118	    );
119	    const auditRaw = await readOptional(join(dir, "audit.json"));
120	    const audit = auditRaw === undefined ? [] : z.array(AuditEvent).parse(auditRaw);
121	    for (const file of imports) {
122	      const { extension, ...info } = file;
123	      await files.importLegacyFile(join(dir, "uploads", `${file.id}${extension}`), info);
124	    }
125	    await mkdir(join(dir, "workflows"), { recursive: true, mode: 0o700 });
126	    for (const workflow of state.workflows) {
127	      const path = join(dir, "workflows", `${workflow.id}.json`);
128	      if (!existsSync(path)) await atomicWrite(path, workflow);
129	    }
130	    if (!existsSync(getSettingsFilePath(dir))) saveSettings(dir, state.settings);
131	    for (const { run: original, outputs, dataset } of artifacts) {
132	      if (known.has(original.id)) continue;
133	      // Import the original state faithfully; the main startup recovery handles
134	      // interrupted current and migrated runs identically, including their audit.
135	      const run = structuredClone(original);
136	      // Atomic per-run import. Retrying after interruption never skips partial artifacts.
137	      db.exec("SAVEPOINT legacy_research_run");
138	      try {
139	        await runs.create(run);
140	        datasets.saveSettings(run.id, state.settings);
141	        for (const [blockId, value] of Object.entries(outputs ?? {}))
142	          await runs.saveBlockOutput(run.id, blockId, value);
143	        if (dataset) datasets.save(run.id, "legacy", dataset, dataset);
144	        db.exec("RELEASE legacy_research_run");
145	      } catch (error) {
146	        db.exec("ROLLBACK TO legacy_research_run; RELEASE legacy_research_run");
147	        throw error;
148	      }
149	    }
150	    const insert = db.prepare(`INSERT OR IGNORE INTO audit_events
151	      (id, at, action, entity_type, entity_id, actor, changes, rationale, run_id, block_id)
152	      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`);
153	    for (const event of audit)
154	      insert.run(
155	        event.id,
156	        event.at,
157	        event.action,
158	        event.entityType,
159	        event.entityId,
160	        JSON.stringify(event.actor),
161	        JSON.stringify(event.changes),
162	        event.rationale ?? null,
163	        event.runId ?? null,
164	        event.blockId ?? null,
165	      );
166	    await atomicWrite(marker, { version: 1, migratedAt: new Date().toISOString() });
167	  } catch (error) {
168	    if (error instanceof ReqflowError) throw error;
169	    throw new ReqflowError(
170	      "storage_error",
171	      "Legacy Research migration failed validation or persistence. Originals were left intact.",
172	    );
173	  }
174	}
