  3	/** Startup recovery only; paused HIL runs remain resumable by the engine. */
  4	export function recoverInterruptedRun(run: WorkflowRun): WorkflowRun {
  5	  if (run.status !== "running" && run.status !== "queued") return run;
  6	  const recovered = structuredClone(run);
  7	  recovered.status = "failed";
  8	  recovered.finishedAt = new Date().toISOString();
  9	  recovered.error =
 10	    "App stopped before run finished; preserved outputs and research remain available.";
 11	  for (const block of recovered.blockRuns) {
 12	    if (["succeeded", "failed", "skipped"].includes(block.status)) continue;
 13	    block.status = block.status === "running" ? "failed" : "skipped";
 14	    block.finishedAt = recovered.finishedAt;
 15	    if (block.status === "failed") block.error = recovered.error;
 16	  }
 17	  return WorkflowRun.parse(recovered);
 18	}
