113	  createInitialRun(workflow: Workflow, startedBy: Actor): WorkflowRun {
114	    workflow = withSplitterWorkplaces(structuredClone(workflow));
115	    const run = WorkflowRun.parse({
116	      id: newId("run"),
117	      workflowId: workflow.id,
118	      workflowVersion: workflow.version,
119	      graph: { blocks: workflow.blocks, edges: workflow.edges },
120	      scope: workflow.scope,
121	      status: "queued",
122	      startedBy,
