186	    const restoredRun = prepareWorkflowRun(normalized, restoredOutputs);
187	    const restoredSettings = Settings.parse(structuredClone(settings));
188	    this.reserve(restoredRun);
189	    this.sessions.set(run.id, {
190	      run: restoredRun,
191	      settings: restoredSettings,
192	      outputs: restoredOutputs,
193	      savedOutputs: structuredClone(restoredOutputs),
194	      savedReferences: new Map(Object.entries(restoredOutputs)),
195	      controller: new AbortController(),
