286	      signal: session.controller.signal,
287	      onUpdate: async (update) => {
288	        await this.publish(session, update);
289	        if (update.status === "queued" || update.status === "running" || audited.has(update.status))
290	          return;
291	        // Pre-start cancellation and recursive skips can publish intermediate cancelled snapshots.
292	        if (
293	          update.status === "cancelled" &&
294	          update.blockRuns.some(
295	            (state) =>
296	              state.status === "pending" ||
297	              state.status === "running" ||
298	              state.status === "waiting_for_review",
299	          )
300	        )
301	          return;
302	        await this.recordAudit(
303	          update.status === "waiting_for_review"
304	            ? "run.paused"
305	            : update.status === "completed"
306	              ? "run.completed"
307	              : update.status === "cancelled"
308	                ? "run.cancelled"
309	                : "run.failed",
310	          update,
311	        );
312	        audited.add(update.status);
