318	  private async fail(session: RunSession, error: unknown): Promise<never> {
319	    // Infrastructure failures must be observable, not mistaken for successful blocks or swallowed.
320	    const run = structuredClone(session.run);
321	    run.status = session.controller.signal.aborted ? "cancelled" : "failed";
322	    run.error = message(error);
323	    run.finishedAt = now();
324	    for (const state of run.blockRuns) {
325	      if (state.status === "succeeded" && session.savedOutputs[state.blockId]) continue;
326	      if (state.status === "failed" || state.status === "skipped") continue;
327	      state.status = state.status === "running" ? "failed" : "skipped";
328	      state.finishedAt = run.finishedAt;
329	      if (state.status === "failed") state.error = run.error;
330	    }
331	    session.run = run;
