    await expect(h.api.runs.start(workflow.id)).rejects.toMatchObject({ code: "run_busy" });

    expect((await h.api.runs.list(workflow.id)).map((run) => run.id)).toEqual([started.id]);
    expect(h.fetchImpl).toHaveBeenCalledTimes(1);
  });

