   127	  async removeAll(): Promise<Requirement[]> {
   128	    const removed = await this.list();
   129	    if (removed.length === 0) return [];
   130	    const placeholders = removed.map(() => "?").join(", ");
   131	    this.db
   132	      .prepare(`DELETE FROM requirements WHERE id IN (${placeholders})`)
   133	      .run(...removed.map((r) => r.id));
