   137	  /**
   138	   * Highest sequence number ever used for ids starting with `prefix` ("REQ-F70-EU-"), counting
   139	   * deleted requirements too: they live on in the audit trail, so their ids must not come back.
   140	   */
   141	  async maxSeq(prefix: string): Promise<number> {
   142	    const like = `${prefix.replace(/[\\%_]/g, "\\$&")}%`;
   143	    const rows = this.db
   144	      .prepare(
   145	        `SELECT id FROM requirements WHERE id LIKE ? ESCAPE '\\'
   146	         UNION SELECT entity_id AS id FROM audit_events
   147	           WHERE entity_type = 'requirement' AND entity_id LIKE ? ESCAPE '\\'`,
   148	      )
   149	      .all(like, like) as Array<{ id: string }>;
   150	    const seqs = rows
   151	      .map((r) => r.id.slice(prefix.length))
   152	      .filter((s) => /^\d+$/.test(s))
   153	      .map(Number);
   154	    return seqs.length ? Math.max(...seqs) : 0;
   155	  }
