 const auditId = await seed(992);
 db.exec("CREATE TRIGGER offline_audit_fault BEFORE INSERT ON audit_events WHEN NEW.action = 'requirement.status_changed' BEGIN SELECT RAISE(ABORT, 'synthetic audit fault'); END;");
 let rejected = false;
