const gate = () => { let resolve; const promise = new Promise(r => { resolve = r; }); return { promise, resolve }; };
const key = 'synthetic-review-only-key';
for (const mode of ['provider disabled', 'Research off', 'credential deleted', 'domain blocked']) {
 const dir = await mkdtemp(join(tmpdir(), 'reqflow-offline-revocation-'));
 const db = createDatabase();
 try {
  const run = WorkflowRun.parse({ id: 'run_synthetic', workflowId: 'wf_synthetic', workflowVersion: 1, graph: { blocks: [], edges: [] }, scope: DEFAULT_SETTINGS.defaultScope, startedBy: {type:'system',component:'offline'}, startedAt: '2026-10-10T00:00:00Z', status: 'running', blockRuns: [] });
  const runs = new SqliteRunRepository(db); await runs.create(run);
  const secrets = new SecretsStore(dir, { environment: {}, secureStorage: { isEncryptionAvailable: () => true, encryptString: s => Buffer.from('cipher:' + s), decryptString: b => b.toString().slice(7) } });
  await secrets.setSecret('firecrawl_api_key', key);
  let settings = structuredClone(DEFAULT_SETTINGS);
  settings.research.provider = 'firecrawl';
  settings.research.apis.firecrawl = ResearchProviderConfig.parse({enabled:true});
  const began = gate(), release = gate();
  let calls = 0, postRevocation = 0, usesOldKey = false, revoked = false;
  const service = createResearchService({ files: createFileStore(join(dir,'uploads')), secrets, datasets: new ResearchDatasetRepository(db), settings: () => settings, saveSettings: s => { settings = s; return s; }, getRun: id => runs.get(id), audit: new SqliteAuditLogger(db), chooseExport: async () => null,
   fetchImpl: async (url, init) => {
    calls++;
    if (revoked) { postRevocation++; usesOldKey ||= init.headers.Authorization === `Bearer ${key}`; }
    if (calls === 1) { began.resolve(); await release.promise; return Response.json({success:true,data:{web:[{url:'https://www.bmwgroup.com/synthetic-review',title:'Synthetic original'}]}}); }
    return Response.json({success:true,data:{markdown:'Synthetic original content.',rawHtml:'<p>Synthetic original content.</p>',metadata:{url:'https://www.bmwgroup.com/synthetic-review',statusCode:200}}});
   }
  });
