  revoked = true; release.resolve();
  const result = await collecting;
  assert.equal(postRevocation,1); assert.equal(usesOldKey,true); assert.equal(result.records.length,1);
  console.log('active collection revocation', {mode, requestsStartedAfterRevocation:postRevocation, retainedCredentialUsed:usesOldKey, originalsPersisted:result.records.length});
